<script setup lang="ts">import{Head,useForm}from'@inertiajs/vue3';defineProps<{sections:any[]}>();function save(s:any){useForm({title:s.content.title,body:s.content.body,is_published:!!s.is_published}).put(`/admin/content/${s.id}`)}</script><template><Head title="CMS Konten"/><main class="min-h-screen bg-neutral-100 p-6"><div class="mx-auto max-w-5xl"><p class="text-sm font-bold uppercase tracking-widest text-orange-600">Content CMS</p><h1 class="text-4xl font-bold">Section & Dokumen</h1><section class="mt-8 space-y-5"><form v-for="s in sections" :key="s.id" class="rounded-2xl bg-white p-6" @submit.prevent="save(s)"><p class="font-mono text-xs text-orange-700">{{s.key}} · revision {{s.revision}}</p><input v-model="s.content.title" required><textarea v-model="s.content.body" required></textarea><div class="mt-4 flex items-center justify-between"><label><input v-model="s.is_published" type="checkbox"> Dipublikasikan</label><button>Simpan revisi</button></div></form></section></div></main></template><style scoped>input,textarea{margin-top:1rem;width:100%;border:1px solid #d4d4d4;border-radius:.75rem;padding:.75rem}textarea{min-height:12rem}label{display:flex;gap:.5rem}label input{margin:0;width:auto}button{border-radius:.75rem;background:#171717;color:white;padding:.75rem 1.25rem}</style>
